        // Check if the message should be printed based on the current timestamp and the configuration
        if (autoIncrementMode) {
            // In auto-increment mode, the message should be printed if the current timestamp minus the last timestamp is greater than or equal to the threshold
            long currentTime = new Date().getTime() / 1000;
            long diff = currentTime - lastTimestamp;
            if (diff >= timestamp) {
                lastTimestamp = currentTime;
                return true;
            }
        } else {
            // In manual mode, the message should be printed if the timestamp is equal to the last printed timestamp
            if (timestamp == lastTimestamp) {
                return true;
            }
        }
        return false;
    }

