public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE && utf8s[offsets[i]] == name && utf8s[offsets[i + 1]] == descriptor) {
            return i;
        }
    }

    // Create a new Symbol with the given name and descriptor
    int nameIndex = addUtf8(name);
    int descriptorIndex = addUtf8(descriptor);
    int nameAndTypeIndex = maxPoolSize;
    types[nameAndTypeIndex] = NAME_TYPE;
    offsets[nameAndTypeIndex] = nameIndex;
    offsets[nameAndTypeIndex + 1] = descriptorIndex;

    // Increase the size of the constant pool
    maxPoolSize++;

    return nameAndTypeIndex;
}

