private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
	// Find the bucket with label minLabel
	int minBucketIndex = -1;
	for (int i = 0; i < bucketsByLabel.size(); i++) {
		if (labels.get(i) == minLabel) {
			minBucketIndex = i;
			break;
		}
	}

	// Move all vertices from the minBucket to the bucket with label 0
	for (Integer vertex : bucketsByLabel.get(minBucketIndex)) {
		labels.set(vertex, 0);
	}

	// Clear the minBucket
	bucketsByLabel.get(minBucketIndex).clear();
}

