public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    TypeVariable<?>[] typeVariables = targetType.getTypeParameters();
    Type[] arguments = parameterizedType.getActualTypeArguments();
    if (arguments.length != typeVariables.length) {
        return null;
    }

    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    for (int i = 0; i < typeVariables.length; i++) {
        typeVariableMap.put(typeVariables[i], arguments[i]);
    }

    Class<?>[] resolvedArguments = new Class<?>[arguments.length];
    for (int i = 0; i < arguments.length; i++) {
        Type argument = arguments[i];
        if (argument instanceof Class<?>) {
            resolvedArguments[i] = (Class<?>) argument;
        } else if (argument instanceof ParameterizedType) {
            resolvedArguments[i] = (Class<?>) ((ParameterizedType) argument).getRawType();
        } else if (argument instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) argument;
            Type resolvedType = typeVariableMap.get(typeVariable);
            if (resolvedType == null) {
                throw new IllegalArgumentException("Unable to resolve type variable " + typeVariable + " for type " + genericType);
            }
            resolvedArguments[i] = (Class<?>) resolvedType;
        } else {
            throw new IllegalArgumentException("Unsupported type " + argument + " for type " + genericType);
        }
    }

    return resolvedArguments;
}

