Class<?> resolveBound(TypeVariable<?> typeVariable) {
    // Check if a bound has been set for the type variable
    Type bound = typeVariable.getBounds()[0];
    if (bound == null) {
        return Unknown.class;
    }

    // If the bound is a class, it is the first bound
    if (bound instanceof Class) {
        return (Class<?>) bound;
    }

    // If the bound is a type variable, recurse
    if (bound instanceof TypeVariable) {
        return resolveBound((TypeVariable<?>) bound);
    }

    // If the bound is an array type, get the component type
    if (bound instanceof GenericArrayType) {
        return resolveBound(((GenericArrayType) bound).getGenericComponentType());
    }

    // If the bound is a parameterized type, get the raw class of the raw type of the first type argument
    if (bound instanceof ParameterizedType) {
        return ((ParameterizedType) bound).getRawType();
    }

    // If the bound is a wildcard type, get the first upper bound
    if (bound instanceof WildcardType) {
        Type[] upperBounds = ((WildcardType) bound).getUpperBounds();
        if (upperBounds.length > 0) {
            return resolveBound(upperBounds[0]);
        }
    }

    return Unknown.class;
}

